// ─────────── Governing rule 3 — shared price settings ($ / % mode) ───────────
// One mode governs a whole section; % resolves against each row's own base
// cost, rounded to the cent before summing; switching modes clears the values.
function psAmt(unit, val, base) {
  const n = parseFloat(val) || 0;
  return unit === "%" ? Math.round(base * n) / 100 : n;
}
function psRowRetail(row, fundOn) {
  const base = parseFloat(row.base) || 0;
  const total = base + psAmt(row.dealerUnit, row.dealer, base) + psAmt(row.teamUnit, row.team, base) + (fundOn ? psAmt(row.fundUnit || "$", row.fund, base) : 0);
  return total.toFixed(2);
}
function pricingMode(pricing) {
  const rows = [pricing && pricing.youth, pricing && pricing.adult].filter(Boolean);
  return rows.some((r) => r.dealerUnit === "%" || r.teamUnit === "%" || r.fundUnit === "%") ? "%" : "$";
}
function switchPricingMode(pricing, mode, fundOn) {
  const conv = (r) => {
    if (!r) return r;
    const next = { ...r, dealerUnit: mode, teamUnit: mode, fundUnit: mode, dealer: "", team: "", fund: "" };
    next.retail = psRowRetail(next, fundOn);
    return next;
  };
  return { ...pricing, youth: conv(pricing.youth), adult: conv(pricing.adult) };
}
function PSModeControl({ mode, onChange, locked }) {
  return (
    <span title="One mode for the whole section — switching clears the entered values" style={{ display: "inline-flex", border: "1px solid #d4d4d8", borderRadius: 6, overflow: "hidden", flexShrink: 0, background: "#fff", ...(locked ? { pointerEvents: "none", opacity: 0.55 } : {}) }}>
      {["$", "%"].map((m2, i) => (
        <button key={m2} type="button" onClick={() => onChange(m2)} style={{
          width: 36, height: 28, border: 0, cursor: "pointer", fontSize: 12.5, fontWeight: 700, fontFamily: "inherit",
          borderLeft: i > 0 ? "1px solid #d4d4d8" : 0,
          background: mode === m2 ? "#0e0e10" : "#fff", color: mode === m2 ? "#fff" : "#6b6b72",
          transition: "background .12s, color .12s"
        }}>{m2}</button>
      ))}
    </span>
  );
}
// The shared PRICE SETTINGS card: header-mounted $ / % control, per-row column
// headers, read-only base cost, prefix affordances, derived retail, and the
// "Retail price visible to customers" footer. bare = body only (no card chrome).
function PriceSettingsCard({ pricing, onChange, fundOn, locked, noYouth, bare }) {
  const sizes = noYouth ? ["adult"] : ["youth", "adult"];
  const mode = pricingMode(pricing);
  const cols = fundOn ? "64px 84px 1fr 1fr 1fr 84px" : "72px 96px 1fr 1fr 96px";
  const update = (size, field, value) => {
    const next = { ...pricing, [size]: { ...pricing[size], [field]: value } };
    next[size].retail = psRowRetail(next[size], fundOn);
    onChange(next);
  };
  const setMode = (m2) => { if (m2 !== mode) onChange(switchPricingMode(pricing, m2, fundOn)); };
  const body = (
    <React.Fragment>
      <div style={locked ? { pointerEvents: "none" } : undefined}>
        {sizes.map((size, i) => (
          <div key={size} style={{ paddingTop: i > 0 ? 16 : 0, borderTop: i > 0 ? "1px solid #ececf0" : 0, marginTop: i > 0 ? 16 : 0 }}>
            <div style={{ display: "grid", gridTemplateColumns: cols, gap: 16, fontSize: 11, fontWeight: 700, letterSpacing: ".08em", color: "#9a9aa1", marginBottom: 10 }}>
              <div>SIZE</div><div>BASE COST</div><div>DEALER PROFIT</div><div>TEAM PROFIT</div>{fundOn && <div>FUNDRAISING</div>}<div>RETAIL</div>
            </div>
            <div style={{ display: "grid", gridTemplateColumns: cols, gap: 16, alignItems: "center" }}>
              <div style={{ fontSize: 14, fontWeight: 800, color: "#0e0e10" }}>{size.toUpperCase()}</div>
              <div style={{ fontSize: 13, color: "#6b6b72" }}>{"$" + pricing[size].base}</div>
              <ProfitInput unit={mode} value={pricing[size].dealer} onValue={(v) => update(size, "dealer", v)} />
              <ProfitInput unit={mode} value={pricing[size].team} onValue={(v) => update(size, "team", v)} />
              {fundOn && <ProfitInput unit={mode} value={pricing[size].fund ?? ""} onValue={(v) => update(size, "fund", v)} />}
              <div style={{ fontSize: 14, fontWeight: 700, color: "#0e0e10" }}>{"$" + pricing[size].retail}</div>
            </div>
          </div>
        ))}
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 16, marginTop: 16, paddingTop: 14, borderTop: "1px solid #ececf0" }}>
        <span style={{ fontSize: 12.5, color: "#9a9aa1" }}>Retail price visible to customers</span>
        <span style={{ fontSize: 12.5, color: "#9a9aa1" }}>
          {sizes.map((size, i) => (
            <React.Fragment key={size}>
              <span style={{ fontWeight: 700, letterSpacing: ".06em", marginLeft: i > 0 ? 16 : 0 }}>{size.toUpperCase() + " "}</span>
              <strong style={{ color: "#0e0e10" }}>{"$" + pricing[size].retail}</strong>
            </React.Fragment>
          ))}
        </span>
      </div>
      {!locked && (
        <div style={{ fontSize: 11.5, color: "#9a9aa1", marginTop: 8 }}>
          {mode === "%" ? "Percentages apply to each size's own base cost. " : ""}Switching $ / % clears the entered values.
        </div>
      )}
    </React.Fragment>
  );
  if (bare) return <div style={locked ? { opacity: 0.55 } : undefined}>{body}</div>;
  return (
    <div style={{ border: "1px solid #ececf0", borderRadius: 10, padding: "20px 24px", ...(locked ? { opacity: 0.55 } : {}) }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, marginBottom: 16 }}>
        <span style={{ fontSize: 12, fontWeight: 800, letterSpacing: ".10em", color: "#0e0e10" }}>PRICE SETTINGS</span>
        <PSModeControl mode={mode} onChange={setMode} locked={locked} />
      </div>
      {body}
    </div>
  );
}

